-- ===== Internal errors =====

SELECT pmod(10, INTERVAL '1-2' YEAR TO MONTH);

SELECT 7.5BD % INTERVAL 1 DAY;

SELECT array_sort(array('b', NULL, 'a'), (left, right) -> CASE WHEN left IS NULL THEN 1 WHEN right IS NULL THEN 1e309 - 1 ELSE 0 END);

SELECT array_sort(array(1, 2), (l, r) -> CAST(l - r AS BIGINT));
-- ===== Integral literals outside their type's range: DuckDB's __cast threw without being marked fallible (assert builds) =====

SELECT 92233720368549999999999999999999999999999999999999999775807L ^ -1L;

SELECT 128Y, 32768S;

SELECT CAST(99999999999999999999999999999999999999991 AS UBIGINT);

-- @upstream DuckDB v2.0.0: TRY_CAST from BIGNUM throws (INTERNAL: __cast not marked fallible), also without the extension
-- @dialect duckdb
SELECT TRY_CAST(CAST('99999999999999999999999999999999999999991' AS BIGNUM) AS UBIGINT);

